arguments.command:
python3 - <<'PY'
import json
from pathlib import Path
p=Path('/root/mailer_policy_analysis.json')
data=json.loads(p.read_text())
expected={'patients_per_medication','fills_per_year_45_day','fills_per_year_90_day','doses_per_fill_45_day','doses_per_fill_90_day','switch_threshold_usd'}
assert set(data['assumptions'])==expected and len(data['assumptions'])==6
meds=data['medications']
assert isinstance(meds,list) and meds==sorted(meds,key=lambda r:r['medication'])
assert isinstance(data['recommendation'],dict) and set(data['recommendation'])=={'decision','justification'}

def check_round(x,path=''):
    if isinstance(x,dict):
        for k,v in x.items(): check_round(v,f'{path}.{k}' if path else k)
    elif isinstance(x,list):
        for i,v in enumerate(x): check_round(v,f'{path}[{i}]')
    elif isinstance(x,float):
        assert round(x,2)==x, (path,x)
check_round(data)
assert data['totals']['absolute_total_margin_difference_usd']==abs(data['totals']['total_annual_margin_difference_90_minus_45_usd'])
lines=[line for line in Path('/root/mailer_policy_summary.md').read_text().splitlines() if line.strip()]
assert 4 <= len(lines) <= 8
for phrase in ['Total 45-day margin (USD)', 'Total 90-day margin (USD)', 'Absolute difference (USD)', data['recommendation']['decision']]:
    assert any(phrase in line for line in lines), phrase
print('validation ok')
PY
if [ -f /root/test_output.py ]; then python3 -m pytest /root/test_output.py -v 2>&1 | head -80; else echo 'no test_output.py'; fi

